const BASE = "https://api.lokalise.com/api2";
const PID = "31393214664f295f94dd86.76792605";
const PAGES_TO_SCAN = 3;
const LANGS = [{iso:"da",id:767},{iso:"de",id:666},{iso:"et",id:10154},{iso:"fr",id:673},{iso:"it",id:734},{iso:"lt",id:10152},{iso:"lv",id:10153},{iso:"nl",id:737},{iso:"no",id:759},{iso:"pl",id:748},{iso:"pt",id:708},{iso:"sv",id:754},{iso:"th",id:753}];
const out = [];
for (const L of LANGS) {
  for (let p = 1; p <= PAGES_TO_SCAN; p++) {
    out.push({ json: { iso: L.iso, langId: L.id, page: p, pid: PID,
      url: BASE + "/projects/" + PID + "/keys?limit=200&page=" + p
        + "&include_translations=1&filter_untranslated=1&filter_translation_lang_ids=640," + L.id } });
  }
}
return out;

// segments per run = MAX_BATCHES x CHUNK. 40 x 25 = 1000. Set 20 for 500/night.
const CHUNK = 25;
const MAX_BATCHES = 40;
const MODEL = "gpt-4o";
const NL = String.fromCharCode(10);

const SHARED = [
"PRODUCT CONTEXT - Personality.co. A self-knowledge product: personality-type reports, trait reports (bipolar traits, OCD, sociopathy, psychopathy, neurodivergence, anxiety), archetype profiles and Enneagram content. Register is warm, direct, non-clinical self-care advice. Never diagnostic, never clinical-sounding, never anything that reads as replacing therapy. Trait levels describe tendencies, not conditions.",
"Describe a personality type as a group and name the group rather than using a bare pronoun. Lead with the strength before the limitation. The test has no questions to answer - use the product framing of statements or prompts.",
"KEY NAMESPACE DETERMINES REGISTER. components::members::profile::CODE::level_N::* is trait-report body prose: full sentences with final punctuation. A key ending ::name is a short label: no final period. ::growth_and_balance::N::title is a heading: no final period. ::content::start and ::content::end are the lead-in and closing sentence around a list: keep the trailing colon or full stop exactly as in the source. ::content::list::N is a bullet fragment: never expand it into a full sentence and add no final period unless the source has one. Match the sub-register of each list - a gerund list stays nominal or infinitive, an imperative list stays imperative. components::modals::* and components::global::* are UI strings. email_templates::* is email copy. pages::landing::* and pages::get_results::* are marketing copy and may be freer.",
"ARCHETYPE GENDER. Keys prefixed ma_ are the MASCULINE archetype set. The unprefixed set - maiden, queen, mystic, nurturer, lover, rebel, sage, warrior - is FEMININE. Four names are identical in English across both sets: The Lover, The Rebel, The Sage, The Warrior. Where the language marks gender, render a ma_ key in the masculine and an unprefixed key in the feminine. Where the language does not mark gender, translate faithfully and do not invent a distinction. Archetype names must be TRANSLATED, never left in English.",
"LOANWORDS. Some single-word UI labels are the same word in the target language - Stress, Timer, Checklist and similar are borrowed wholesale into the Germanic and several other languages. Where the correct translation genuinely is the English word, use it. Do not invent an awkward native coinage just to look different from the source.",
"WHITESPACE. Some source strings end with a single trailing space because they concatenate with a list or another fragment at runtime. If the source ends with a space, your translation MUST end with a space too. If the source does not, yours must not either.",
"CAPITALISATION - THE MOST FREQUENT FAILURE. The English source writes headings and short labels in Title Case With Every Word Capitalised. That is an English convention and must NEVER be carried across. The strings most at risk are the short ones - keys ending ::name and ::title - because they consist of nothing but a title-cased phrase with no surrounding sentence to show you the register. Treat every such heading as prose: apply your language's ordinary capitalisation rules to it exactly as if it appeared mid-paragraph. Worked examples are given in your style guide below - follow their pattern. Proper nouns, brand names and any product names listed in your guide keep their capitals.",
"HARD RULES. Copy every placeholder exactly and never translate a placeholder name. Copy every HTML tag and attribute exactly, adding and removing none. Never use the ellipsis character or the non-breaking hyphen U+2011; where the source has three periods, write three periods. Never invent content - if the source is a fragment the translation stays a fragment. The glossary overrides the style guide. Return the translation only, with no commentary."
].join(" ");

const G = {
da: "Danish. Address the user as du, never De. Informal, helpful, engaging yet professional; active voice. Clarity over literalness - rephrase freely so it reads as Danish while keeping the message. Avoid noun-heavy phrasing and over-use of possessive pronouns. Exclamation marks and superlatives sparingly. Gender-neutral wording where possible, so ophavsperson rather than ophavsmand. CAPITALISATION: normal Danish orthography - a capital on the first word only, plus proper nouns. Danish does NOT capitalise nationality adjectives, language names, weekdays or months. WORKED EXAMPLES for headings: Moderate Emotional Detachment becomes Moderat folelsesmaessig distance, NOT Moderat Folelsesmaessig Distance. Low Empathy and Emotional Responsiveness becomes Lav empati og folelsesmaessig responsivitet. Buttons and CTAs: imperative. Descriptive headlines: infinitive. UI element names: capitalise the first letter only and use NO quotation marks even if the source has them. QUOTES: straight ASCII double quotation marks. Traditional comma. Full stop on complete sentences, none in headlines. Hyphen for ranges, never an em dash.",
