};

const PUNCT_EXEMPT = { th: true, ko: true };

const gr = $('Fetch glossary').first().json || {};
const gb = gr.body !== undefined ? gr.body : gr;
const GLOSS = {};
for (const t of (gb.data || gb.glossary_terms || [])) {
  const term = (t.term || '').trim();
  if (term.length < 3) continue;
  const noTx = t.translatable === false || t.forbidden === true;
  for (const tr of (t.translations || [])) {
    const iso = tr.langIso || tr.lang_iso;
    if (!iso) continue;
    if (!GLOSS[iso]) GLOSS[iso] = {};
    if (noTx) GLOSS[iso][term] = "KEEP IN ENGLISH, do not translate";
    else { const v = (tr.translation || '').trim(); if (v) GLOSS[iso][term] = v; }
  }
}

const items = $input.all();
const plans = $('Plan').all().map(p => p.json);
const byLang = {};
const JUNK = /^\s*(<p>)?\s*(test[\s_0-9]*|test text|test_key|question|englishtext)\s*(<\/p>)?\s*$/i;
for (let i = 0; i < items.length; i++) {
  const r = items[i].json || {};
  const b = r.body !== undefined ? r.body : r;
  const P = plans[i];
  if (!P || !Array.isArray(b.keys)) continue;
  if (!byLang[P.iso]) byLang[P.iso] = { iso: P.iso, langId: P.langId, pid: P.pid, rows: [], seen: {} };
  const A = byLang[P.iso];
  for (const k of b.keys) {
    if (k.is_archived) continue;
    if (A.seen[k.key_id]) continue;
    const kn = (k.key_name && (k.key_name.web || k.key_name.other)) || '';
    if (!kn) continue;
    let src = '', hasTarget = false, targetEmpty = false;
    for (const t of (k.translations || [])) {
      if (t.language_iso === 'en') { src = t.translation || ''; continue; }
      if (t.language_iso === P.iso) { hasTarget = true; targetEmpty = !t.translation || String(t.translation).trim() === ''; }
    }
    if (!hasTarget || !targetEmpty) continue;
    if (!String(src).trim()) continue;
    if (JUNK.test(src)) continue;
    A.seen[k.key_id] = true;
    A.rows.push({ id: k.key_id, k: kn, s: src });
  }
}

const perLang = [];
for (const iso of Object.keys(byLang)) {
  const L = byLang[iso];
  const chunks = [];
  for (let i = 0; i < L.rows.length; i += CHUNK) chunks.push(L.rows.slice(i, i + CHUNK));
  perLang.push({ L: L, chunks: chunks });
}
const ordered = [];
const depth = Math.max.apply(null, perLang.map(p => p.chunks.length).concat([0]));
for (let d = 0; d < depth && ordered.length < MAX_BATCHES; d++) {
  for (const p of perLang) {
    if (ordered.length >= MAX_BATCHES) break;
    if (p.chunks[d]) ordered.push({ L: p.L, chunk: p.chunks[d] });
  }
}

const out = [];
for (const o of ordered) {
  const iso = o.L.iso, chunk = o.chunk;
  const gl = GLOSS[iso] || {};
  const glLines = Object.keys(gl)
    .filter(t => chunk.some(c => c.s.toLowerCase().indexOf(t.toLowerCase()) > -1))
    .slice(0, 60)
    .map(t => '- ' + t + ' = ' + gl[t]);
  const system = SHARED + NL + NL + 'TARGET LANGUAGE STYLE GUIDE' + NL + (G[iso] || '')
    + (glLines.length ? NL + NL + 'GLOSSARY, binding, overrides the style guide' + NL + glLines.join(NL) : '')
    + NL + NL + 'Return ONLY a JSON object shaped {"t":[{"i":0,"v":"translation"}]} with exactly one entry per input item, in order, using the same i values.';
  const user = JSON.stringify(chunk.map((c, n) => ({ i: n, key: c.k, src: c.s })));
  out.push({ json: {
    iso: iso, langId: o.L.langId, pid: o.L.pid,
    ids: chunk.map(c => c.id), srcs: chunk.map(c => c.s), keys: chunk.map(c => c.k),
    glossaryTermsUsed: glLines.length,
    punctExempt: !!PUNCT_EXEMPT[iso],
    body: { model: MODEL, temperature: 0.2,
      response_format: { type: 'json_object' },
      messages: [ { role: 'system', content: system }, { role: 'user', content: user } ] }
  }});
}
return out;

const all = $input.all().map(i => i.json).filter(a => a && a.iso);
const perLang = {}; const reasons = {}; const samples = []; const apiErrors = [];
let req = 0, acc = 0, rej = 0, conf = 0, rep = 0;
for (const a of all) {
  if (!perLang[a.iso]) perLang[a.iso] = { requested: 0, accepted: 0, rejected: 0, repaired: 0, confirmed: 0 };
  const P = perLang[a.iso];
  P.requested += a.requested || 0; P.accepted += a.accepted || 0;
  P.rejected += a.rejected || 0; P.repaired += a.repaired || 0;
  P.confirmed += a.confirmed_mt_to_review || 0;
  req += a.requested || 0; acc += a.accepted || 0; rej += a.rejected || 0;
  rep += a.repaired || 0; conf += a.confirmed_mt_to_review || 0;
  for (const x of (a.rejects || [])) {
    for (const rs of x.reasons) reasons[rs.split(':')[0]] = (reasons[rs.split(':')[0]] || 0) + 1;
    if (samples.length < 30) samples.push({ iso: a.iso, key: x.key, src: x.src, out: x.out, reasons: x.reasons });
  }
  if (a.lokaliseStatus !== 200 || (a.lokaliseErrors || []).length || a.parseErr || a.rawError) {
    apiErrors.push({ iso: a.iso, lokalise: a.lokaliseStatus, openai: a.openaiStatus, parseErr: a.parseErr, errors: a.lokaliseErrors, raw: a.rawError });
  }
}
return [{ json: {
  run_at: new Date().toISOString(),
  batches: all.length, requested: req, accepted: acc, rejected: rej, repaired: rep,
  confirmed_written_mt_to_review: conf,
  reject_rate_pct: req ? Math.round(1000 * rej / req) / 10 : 0,
  reject_reasons: reasons, per_language: perLang,
  api_errors: apiErrors, reject_samples: samples
} }];

const MT_TO_REVIEW = 29251;
const r = $input.first().json || {};
const b = r.body !== undefined ? r.body : r;
const ctx = $('Batch loop').first().json;
const iso = ctx.iso;

const PH = /%[sd]|%\d+\$[sd]|\{\{[^}]*\}\}|\{[^}]*\}|\[%[^\]]*\]|%LANG_ISO%/g;
const TAG = /<[^>]+>/g;
// English puts the sentence period INSIDE the closing quote; most target
// languages put it outside. Strip trailing quotes from both before comparing.
const TRAILQ = /["'\u00AB\u00BB\u201C\u201D\u201E\u201F\u2018\u2019\u201A\u203A\u2039]+$/;
const NONLATIN = { th: true, ko: true };
const NOCASECHECK = { de: true, fr: true, th: true, ko: true };
const PROTECT = /^(Personality|Personality\.co|Enneagram\w*|Eneagrama|Enn[ée]agramm?e?|OCD|QR|PDF|DNT|Apple|Android|Google|Teste|Relat[óo]rio|Pol[íi]tica|Termos|[ÁA]rea|Privacidade|Uso|Membros|Carreira|Personalidade)$/;
const ALLOWED_LATIN = /^(Personality|Personality\.co|OCD|QR|PDF|DNT|Apple|Android|Google|iOS|AI)$/i;

function ms(s, re) { return ((s || '').match(re) || []).slice().sort().join('|'); }
function strip(s) { return String(s || '').replace(TAG, ' ').replace(PH, ' '); }
function words(s) { return String(s || '').trim().split(/\s+/).filter(Boolean).length; }
function toks(s) { const o = []; const re = /\S+/g; let m; while ((m = re.exec(String(s || ''))) !== null) o.push([m[0], m.index]); return o; }
function core(t) { return t.replace(/^[^\p{L}]+|[^\p{L}]+$/gu, ''); }
function isCap(w) { const f = w.charAt(0); return f === f.toUpperCase() && f !== f.toLowerCase(); }
function starts(tk) {
  const S = { 0: true };
  for (let i = 1; i < tk.length; i++) {
    const p = tk[i - 1][0];
    if (/[.!?:;]$/.test(p) || /[\u25cf\u2022\u25aa>]$/.test(p) || /^\(\s*[\p{L}\d]{1,3}\s*\)$/u.test(p) || /^\d+[.)]$/.test(p) || /^<[^>]*>$/.test(p)) S[i] = true;
  }
  return S;
}
function capProfile(s) {
  const tk = toks(strip(s)), S = starts(tk);
  let caps = 0, wc = 0;
  for (let i = 0; i < tk.length; i++) {
    if (S[i]) continue;
    const c = core(tk[i][0]);
    if (!c || c.length < 2 || c === c.toUpperCase()) continue;
    if (PROTECT.test(c)) continue;
    wc++;
    if (isCap(c)) caps++;
  }
  return { caps: caps, words: wc };
}

let parsed = null, parseErr = null;
try { parsed = JSON.parse(((b.choices || [])[0] || {}).message.content); }
catch (e) { parseErr = String(e).slice(0, 200); }

const byIdx = {};
for (const e of (parsed && Array.isArray(parsed.t) ? parsed.t : [])) {
  if (e && typeof e.i === 'number') byIdx[e.i] = e.v;
}

const accepted = [], rejected = [], repaired = [];
for (let n = 0; n < ctx.ids.length; n++) {
  const src = ctx.srcs[n], key = ctx.keys[n], id = ctx.ids[n];
  let v = byIdx[n];
  const fail = [];
  const fixes = [];
  if (typeof v !== 'string' || !v.trim()) fail.push('missing or empty');
  else {
    // Whitespace on a concatenating source is deterministic - repair, do not reject.
    if (src.slice(-1) === ' ' && v.slice(-1) !== ' ') { v = v + ' '; fixes.push('restored trailing space'); }
    else if (src.slice(-1) !== ' ' && v.slice(-1) === ' ') { v = v.replace(/\s+$/, ''); fixes.push('trimmed trailing space'); }
    if (src.charAt(0) === ' ' && v.charAt(0) !== ' ') { v = ' ' + v; fixes.push('restored leading space'); }
    else if (src.charAt(0) !== ' ' && v.charAt(0) === ' ') { v = v.replace(/^\s+/, ''); fixes.push('trimmed leading space'); }

    if (ms(src, PH) !== ms(v, PH)) fail.push('placeholder mismatch');
    if (ms(src, TAG) !== ms(v, TAG)) fail.push('html mismatch');
    if (v.indexOf('\u2011') > -1 || v.indexOf('\u2026') > -1) fail.push('withdrawn character');

    // Passthrough: a multi-word English sentence returned verbatim is a failure.
    // A single-word label matching is normal - Stress, Timer, Checklist and the
    // like are borrowed wholesale into Danish, Dutch, German, Norwegian, Swedish.
    if (v.trim() === src.trim() && words(src) >= 2) fail.push('untranslated passthrough');
    if (NONLATIN[iso]) {
      const runs = strip(v).match(/[A-Za-z][A-Za-z.\-]{2,}/g) || [];
      const bad = runs.filter(x => !ALLOWED_LATIN.test(x.replace(/[.\-]+$/, '')));
      if (bad.length) fail.push('untranslated Latin text: ' + bad.slice(0, 4).join(' '));
    }
    if (!NOCASECHECK[iso]) {
      const S = capProfile(src), T = capProfile(v);
      const srcTitle = S.caps >= 2 && S.words >= 2 && S.caps / S.words >= 0.5;
      if (srcTitle && T.caps >= 2 && T.words >= 2 && T.caps / T.words >= 0.5) fail.push('English title case carried over');
    }
    const se = src.trim().replace(TRAILQ, '').slice(-1);
    const ve = v.trim().replace(TRAILQ, '').slice(-1);
    if (!ctx.punctExempt) {
      if ((se === '.' || se === ':') && ve !== se) fail.push('terminal punctuation dropped');
      if ('.:'.indexOf(se) === -1 && '.:'.indexOf(ve) > -1) fail.push('terminal punctuation added');
    }
    if (v.length > Math.max(400, src.length * 3.5)) fail.push('length runaway');
  }
  if (fail.length) rejected.push({ key_id: id, key: key, src: src.slice(0, 140), out: (typeof v === 'string' ? v.slice(0, 140) : null), reasons: fail });
  else {
    accepted.push({ key_id: id, translation: v });
    if (fixes.length) repaired.push({ key_id: id, key: key, fixes: fixes });
  }
}

const payload = { keys: accepted.map(a => ({
  key_id: a.key_id,
  translations: [{ language_iso: iso, translation: a.translation,
    is_reviewed: false, is_fuzzy: true, custom_translation_status_ids: [MT_TO_REVIEW] }]
})) };

return [{ json: {
  iso: iso, pid: ctx.pid, glossaryTermsUsed: ctx.glossaryTermsUsed,
  requested: ctx.ids.length, accepted: accepted.length, rejected: rejected.length,
  repaired: repaired.length, repairs: repaired.slice(0, 10),
  parseErr: parseErr, openaiStatus: r.statusCode, rejects: rejected,
  url: 'https://api.lokalise.com/api2/projects/' + ctx.pid + '/keys',
  payload: accepted.length ? payload : { keys: [] }
} }];

const r = $input.first().json || {};
const b = r.body !== undefined ? r.body : r;
const v = $('Validate').first().json;
const keys = Array.isArray(b.keys) ? b.keys : [];
let confirmed = 0;
for (const k of keys) {
  for (const t of (k.translations || [])) {
    if (t.language_iso !== v.iso) continue;
    const st = (t.custom_translation_statuses || []).map(s => s.status_id);
    if (t.translation && t.is_fuzzy === true && st.indexOf(29251) > -1) confirmed++;
  }
}
return [{ json: {
  iso: v.iso, requested: v.requested, accepted: v.accepted, rejected: v.rejected,
  repaired: v.repaired, glossaryTermsUsed: v.glossaryTermsUsed, keys_returned: keys.length,
  confirmed_mt_to_review: confirmed, openaiStatus: v.openaiStatus, parseErr: v.parseErr,
  lokaliseStatus: r.statusCode, lokaliseErrors: Array.isArray(b.errors) ? b.errors : [],
  rawError: (v.accepted > 0 && keys.length === 0) ? JSON.stringify(b).slice(0, 400) : null,
  rejects: v.rejects
} }];
